#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct DocInfo {
    pub title: String,
    pub author: String,
    pub subject: String,
    pub keywords: String,
    pub notes: String,
}

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Default)]
pub struct Pos {
    pub p: usize,
    pub c: usize,
}

impl Pos {
    pub fn new(p: usize, c: usize) -> Self {
        Self { p, c }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct Document {
    pub paras: Vec<Para>,
    pub page: PageSetup,
    pub header: String,
    pub footer: String,
    pub info: DocInfo,
}

impl Default for Document {
    fn default() -> Self {
        Self {
            paras: vec![Para::new(CharStyle::default(), ParaFmt::default())],
