    pub fn char_at_x(&self, li: usize, x: f32) -> usize {
        let l = &self.lines[li];
        let rel = x - l.x;
        let n = l.end - l.start;
        for k in 0..n {
            let mid = (l.xs[k] + l.xs[k + 1]) / 2.0;
            if rel < mid {
                return l.start + k;
            }
        }
