use eframe::egui::{self, Color32, CornerRadius, Stroke};

#[derive(Clone)]
pub struct Theme {
    pub dark: bool,
    pub accent: Color32,
    pub workspace: Color32,
    pub chrome: Color32,
    pub toolbar: Color32,
    pub border: Color32,
    pub page_border: Color32,
    pub guide: Color32,
    pub selection: Color32,
    pub find_highlight: Color32,
    pub caret: Color32,
    pub text: Color32,
    pub subtle: Color32,
    pub icon: Color32,
    pub hover: Color32,
    pub active: Color32,
}

impl Theme {
    pub fn light() -> Self {
        Self {
            dark: false,
            accent: Color32::from_rgb(37, 99, 235),
            workspace: Color32::from_rgb(228, 231, 236),
            chrome: Color32::from_rgb(249, 250, 251),
            toolbar: Color32::from_rgb(255, 255, 255),
            border: Color32::from_rgb(222, 225, 230),
