    // ───── toolbar (modern replacement for the SmartIcons bar) ─────
    fn toolbar(&mut self, ui: &mut egui::Ui, th: &Theme) {
        let t = self.tab_ref();
        let st = t.typing_style();
        let fmt = t.doc.paras[t.doc.clamp(t.caret).p].fmt;
        let has_sel = t.has_selection();
        let (can_undo, can_redo) = (t.can_undo(), t.can_redo());
        let style_name = t.current_style_name();

        macro_rules! b {
            ($icon:expr, $tip:expr, $sel:expr, $en:expr, $act:expr) => {
                if icon_button(ui, th, $icon, $tip, $sel, $en).clicked() {
                    self.act($act);
                }
            };
        }
        b!(Icon::New, "New document (Ctrl+N)", false, true, Action::New);
        b!(Icon::Open, "Open (Ctrl+O)", false, true, Action::Open);
        b!(Icon::Save, "Save (Ctrl+S)", false, true, Action::Save);
        b!(Icon::Export, "Export as Rich Text", false, true, Action::ExportRtf);
        sep(ui, th);
        b!(Icon::Undo, "Undo (Ctrl+Z)", false, can_undo, Action::Undo);
        b!(Icon::Redo, "Redo (Ctrl+Y)", false, can_redo, Action::Redo);
        sep(ui, th);
        b!(Icon::Cut, "Cut (Ctrl+X)", false, has_sel, Action::Cut);
        b!(Icon::Copy, "Copy (Ctrl+C)", false, has_sel, Action::Copy);
        b!(Icon::Paste, "Paste (Ctrl+V)", false, true, Action::Paste);
        sep(ui, th);

        // named style
        let styles = named_styles();
        egui::ComboBox::from_id_salt("style-combo").width(118.0).selected_text(style_name).show_ui(ui, |ui| {
            for (i, s) in styles.iter().enumerate() {
                let (fam, _) = self.book.family(s.chr.font, s.chr.bold, s.chr.italic);
                let size = (s.chr.size * 0.9).clamp(11.0, 20.0);
                if ui.selectable_label(s.name == style_name, RichText::new(s.name).font(FontId::new(size, fam))).clicked() {
                    self.act(Action::Style(i));
                }
            }
        });
        // font
        egui::ComboBox::from_id_salt("font-combo").width(150.0).selected_text(FONT_NAMES[st.font as usize % FONT_NAMES.len()]).height(420.0).show_ui(ui, |ui| {
            for (i, name) in FONT_NAMES.iter().enumerate() {
                let (fam, _) = self.book.family(i as u8, false, false);
                if ui.selectable_label(st.font as usize == i, RichText::new(*name).font(FontId::new(15.0, fam))).clicked() {
                    self.act(Action::Font(i as u8));
                }
            }
        });
        // size
        let size_txt = if st.size.fract() == 0.0 { format!("{}", st.size as i32) } else { format!("{:.1}", st.size) };
        egui::ComboBox::from_id_salt("size-combo").width(46.0).selected_text(size_txt).height(360.0).show_ui(ui, |ui| {
            for s in SIZE_LIST {
                if ui.selectable_label((st.size - s).abs() < 0.01, format!("{}", *s as i32)).clicked() {
                    self.act(Action::Size(*s));
                }
            }
        });
        b!(Icon::Grow, "Enlarge text (F4)", false, true, Action::Grow);
        b!(Icon::Shrink, "Reduce text (Shift+F4)", false, true, Action::Shrink);
        sep(ui, th);
        b!(Icon::Bold, "Bold (Ctrl+B)", st.bold, true, Action::Bold);
        b!(Icon::Italic, "Italic (Ctrl+I)", st.italic, true, Action::Italic);
        b!(Icon::Underline, "Underline (Ctrl+U)", st.underline, true, Action::Underline);
        b!(Icon::Strike, "Strikethrough", st.strike, true, Action::Strike);
        b!(Icon::Superscript, "Superscript", st.script > 0, true, Action::Script(1));
        b!(Icon::Subscript, "Subscript", st.script < 0, true, Action::Script(-1));
        // text colour
        let r = icon_button(ui, th, Icon::TextColor, "Text colour", false, true);
        egui::Popup::menu(&r).show(|ui| {
            ui.label("Text colour");
            egui::Grid::new("pal").spacing(vec2(4.0, 4.0)).show(ui, |ui| {
                for (i, c) in PALETTE.iter().enumerate() {
                    if swatch(ui, *c, st.color == *c).clicked() {
                        self.act(Action::Color(*c));
                        ui.close();
                    }
                    if i % 5 == 4 {
                        ui.end_row();
                    }
                }
            });
        });
        let r = icon_button(ui, th, Icon::Highlight, "Highlight", st.highlight.is_some(), true);
        egui::Popup::menu(&r).show(|ui| {
            ui.label("Highlight");
            ui.horizontal(|ui| {
                for c in HIGHLIGHTS {
                    if swatch(ui, *c, st.highlight == Some(*c)).clicked() {
                        self.act(Action::Highlight(Some(*c)));
                        ui.close();
                    }
                }
            });
            if ui.button("No highlight").clicked() {
                self.act(Action::Highlight(None));
                ui.close();
            }
        });
        b!(Icon::Clear, "Normal — clear formatting (Ctrl+Space)", false, true, Action::ClearFormat);
        sep(ui, th);
        b!(Icon::AlignLeft, "Align left (Ctrl+L)", fmt.align == Align::Left, true, Action::Align(Align::Left));
        b!(Icon::AlignCenter, "Center (Ctrl+E)", fmt.align == Align::Center, true, Action::Align(Align::Center));
        b!(Icon::AlignRight, "Align right (Ctrl+R)", fmt.align == Align::Right, true, Action::Align(Align::Right));
        b!(Icon::AlignJustify, "Full justify (Ctrl+J)", fmt.align == Align::Justify, true, Action::Align(Align::Justify));
        sep(ui, th);
        b!(Icon::Bullets, "Bullets", fmt.list == ListKind::Bullet, true, Action::List(ListKind::Bullet));
        b!(Icon::Numbers, "Numbers", fmt.list == ListKind::Number, true, Action::List(ListKind::Number));
        b!(Icon::Outdent, "Outdent (Shift+Tab)", false, fmt.indent > 0, Action::Indent(-1));
        b!(Icon::Indent, "Indent (Tab)", false, true, Action::Indent(1));
        sep(ui, th);
        b!(Icon::PageBreak, "Insert page break (Ctrl+Enter)", false, true, Action::PageBreak);
        b!(Icon::DateTime, "Insert date/time", false, true, Action::Dialog(Dialog::DateTime));
        b!(Icon::Symbol, "Insert symbol", false, true, Action::Dialog(Dialog::Symbol));
        sep(ui, th);
        b!(Icon::Find, "Find & replace (Ctrl+F)", matches!(self.dialog, Dialog::Find(_)), true, Action::Dialog(Dialog::Find(true)));
        b!(Icon::WordCount, "Word count", false, true, Action::Dialog(Dialog::WordCount));
        b!(Icon::PageSetup, "Page setup", false, true, Action::Dialog(Dialog::PageSetup));
        if icon_button(ui, th, Icon::Marks, "Show paragraph marks", self.show_marks, true).clicked() {
            self.show_marks = !self.show_marks;
        }
        sep(ui, th);
        b!(Icon::FullPage, "Full page", self.zoom_mode == ZoomMode::FullPage, true, Action::ZoomMode(ZoomMode::FullPage));
        b!(Icon::PageWidth, "Page width", self.zoom_mode == ZoomMode::PageWidth, true, Action::ZoomMode(ZoomMode::PageWidth));
        let icon = if self.cfg.dark { Icon::Sun } else { Icon::Moon };
        b!(icon, "Switch light / dark theme", false, true, Action::ToggleDark);
    }

    fn tab_strip(&mut self, ui: &mut egui::Ui, th: &Theme) {
        ui.horizontal(|ui| {
            ui.spacing_mut().item_spacing.x = 4.0;
            let mut close = None;
            let mut select = None;
            for (i, t) in self.tabs.iter().enumerate() {
                let active = i == self.active;
                let fill = if active { th.workspace } else { Color32::TRANSPARENT };
                let resp = Frame::new()
                    .fill(fill)
                    .corner_radius(egui::CornerRadius { nw: 8, ne: 8, sw: 0, se: 0 })
                    .inner_margin(Margin { left: 12, right: 6, top: 5, bottom: 5 })
                    .show(ui, |ui| {
                        ui.horizontal(|ui| {
                            let txt = RichText::new(t.title()).color(if active { th.text } else { th.subtle });
                            let l = ui.add(egui::Label::new(txt).sense(Sense::click()));
                            if l.clicked() {
                                select = Some(i);
                            }
                            let (r, cr) = ui.allocate_exact_size(vec2(18.0, 18.0), Sense::click());
                            if cr.hovered() {
                                ui.painter().rect_filled(r, 4.0, th.hover);
                            }
                            icons::draw(ui.painter(), r.shrink(4.0), Icon::Close, th.subtle, th.accent);
                            if cr.on_hover_text("Close").clicked() {
                                close = Some(i);
                            }
                        });
                    });
                if resp.response.interact(Sense::click()).clicked() {
                    select = Some(i);
                }
            }
            let (r, pr) = ui.allocate_exact_size(vec2(24.0, 24.0), Sense::click());
            if pr.hovered() {
                ui.painter().rect_filled(r, 6.0, th.hover);
            }
            icons::draw(ui.painter(), r.shrink(5.0), Icon::New, th.subtle, th.accent);
            if pr.on_hover_text("New document").clicked() {
                self.act(Action::New);
            }
            if let Some(i) = select {
                self.act(Action::SelectTab(i));
            }
            if let Some(i) = close {
                self.act(Action::Close(i));
            }
        });
    }

    fn status_bar(&mut self, ui: &mut egui::Ui, th: &Theme) {
        let zoom = self.effective_zoom();
        let t = self.tab_ref();
        let pages = t.cached_pages();
        let st = t.typing_style();
        let (chars, words) = t.doc.counts(None);
        let sel_words = if t.has_selection() { let (a, b) = t.selection(); Some(t.doc.counts(Some((a, b))).1) } else { None };
        let style = t.current_style_name();
        let page = t.current_page + 1;
        let path = t.path.as_ref().map(|p| p.display().to_string()).unwrap_or_else(|| "Not saved yet".into());
        let font = FONT_NAMES[st.font as usize % FONT_NAMES.len()];
        ui.horizontal(|ui| {
            let small = |s: String| RichText::new(s).size(12.5).color(th.subtle);
            // " Pg %d" — the original's page indicator (FUN_00452923)
            ui.label(small(format!("Pg {page} of {pages}")));
            ui.separator();
            match sel_words {
                Some(sw) => ui.label(small(format!("{sw} of {words} words"))),
                None => ui.label(small(format!("{words} words"))),
            };
            ui.label(small(format!("{chars} characters")));
            ui.separator();
            ui.label(small(format!("{font} {}", st.size)));
            ui.separator();
            ui.label(small(style.to_string()));
            ui.separator();
            ui.label(small(path));
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                ui.spacing_mut().item_spacing.x = 4.0;
                ui.label(RichText::new(format!("{:>3}%", (zoom * 100.0).round() as i32)).size(12.5).color(th.text).font(FontId::new(12.5, FontFamily::Proportional)));
                if icon_button(ui, th, Icon::ZoomIn, "Zoom in (Ctrl+=)", false, zoom < ZOOM_MAX).clicked() {
                    self.act(Action::ZoomIn);
                }
                let mut z = zoom * 100.0;
                let s = ui.add_sized([140.0, 18.0], egui::Slider::new(&mut z, (ZOOM_MIN * 100.0)..=(ZOOM_MAX * 100.0)).show_value(false));
                if s.changed() {
                    self.act(Action::SetZoom((z / 5.0).round() * 5.0 / 100.0));
                }
                if icon_button(ui, th, Icon::ZoomOut, "Zoom out (Ctrl+-)", false, zoom > ZOOM_MIN).clicked() {
                    self.act(Action::ZoomOut);
                }
                ui.separator();
                if ui.selectable_label(self.draft, small("Draft".into())).clicked() {
                    self.act(Action::Draft(true));
                }
                if ui.selectable_label(!self.draft, small("Layout".into())).clicked() {
                    self.act(Action::Draft(false));
                }
            });
        });
    }

    fn ruler(&mut self, ui: &mut egui::Ui, th: &Theme, zoom: f32) {
        let (rect, _) = ui.allocate_exact_size(vec2(ui.available_width(), 22.0), Sense::hover());
        let p = ui.painter_at(rect);
        p.rect_filled(rect, 0.0, th.chrome);
        p.line_segment([rect.left_bottom(), rect.right_bottom()], Stroke::new(1.0, th.border));
        let t = self.tab_ref();
        let pg = t.doc.page;
        let ppi = BASE_PPI * zoom;
        let page_w = pg.width * ppi;
        let canvas_w = if t.canvas_w > 0.0 { t.canvas_w } else { rect.width() };
        let x0 = if t.canvas_w > 0.0 { t.canvas_x0 } else { rect.min.x } + ((canvas_w - page_w) / 2.0).max(layout::PAGE_GAP);
        let band = egui::Rect::from_min_max(egui::pos2(x0, rect.min.y + 4.0), egui::pos2(x0 + page_w, rect.max.y - 4.0));
        p.rect_filled(band, 2.0, if th.dark { Color32::from_rgb(58, 62, 72) } else { Color32::from_rgb(232, 235, 240) });
        let ml = x0 + pg.margin_left * ppi;
        let mr = x0 + (pg.width - pg.margin_right) * ppi;
        p.rect_filled(egui::Rect::from_min_max(egui::pos2(ml, band.min.y), egui::pos2(mr, band.max.y)), 0.0, if th.dark { Color32::from_rgb(30, 33, 39) } else { Color32::WHITE });
        let n = (pg.width * 8.0) as i32;
        for i in 0..=n {
            let x = ml + (i as f32 - pg.margin_left * 8.0) * ppi / 8.0;
            if x < band.min.x || x > band.max.x {
                continue;
            }
            let k = i - (pg.margin_left * 8.0) as i32;
            let h = if k % 8 == 0 { 0.0 } else if k % 4 == 0 { 6.0 } else if k % 2 == 0 { 4.0 } else { 2.5 };
            if k % 8 == 0 {
                if k != 0 {
                    p.text(egui::pos2(x, band.center().y), egui::Align2::CENTER_CENTER, format!("{}", k.abs() / 8), FontId::proportional(9.5), th.subtle);
                }
            } else if ppi / 8.0 > 3.0 || k % 2 == 0 {
                p.line_segment([egui::pos2(x, band.center().y - h / 2.0), egui::pos2(x, band.center().y + h / 2.0)], Stroke::new(1.0, th.subtle.gamma_multiply(0.7)));
            }
        }
        // indent marker of the current paragraph
        let f = t.doc.paras[t.doc.clamp(t.caret).p].fmt;
        let ix = ml + f.indent as f32 * layout::INDENT_STEP * ppi;
        let tri = vec![egui::pos2(ix - 5.0, band.max.y), egui::pos2(ix + 5.0, band.max.y), egui::pos2(ix, band.max.y - 6.0)];
        p.add(egui::Shape::convex_polygon(tri, th.accent, Stroke::NONE));
        let tri = vec![egui::pos2(mr - 5.0, band.max.y), egui::pos2(mr + 5.0, band.max.y), egui::pos2(mr, band.max.y - 6.0)];
        p.add(egui::Shape::convex_polygon(tri, th.accent, Stroke::NONE));
        let _ = Key::A;
    }
}

input.content:
//! The main window: menus, toolbar, document tabs, ruler, page view and status bar.

use eframe::egui::{self, vec2, Color32, FontFamily, FontId, Frame, Margin, RichText, Sense, Stroke};
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

use crate::dialogs::{self, Dialog, FindState};
use crate::doc::{self, *};
use crate::editor::{Cmd, EditKind, SmartCorrect, Tab, ViewOpts};
use crate::fonts::{self, FontBook};
use crate::icons::{self, Icon};
use crate::layout::{self, BASE_PPI};
use crate::theme::Theme;

pub const ZOOM_MIN: f32 = 0.25; // the person's decision
pub const ZOOM_MAX: f32 = 2.0;
pub const ZOOM_START: f32 = 1.0; // "Standard (100%)"
pub const AUTOSAVE_MIN_DEFAULT: u32 = 10;
pub const APP_NAME: &str = "Scribe Pro";

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ZoomMode {
    Percent,
    PageWidth,
    MarginWidth,
    FullPage,
}

#[derive(Clone, Debug)]
pub enum Action {
    New,
    Open,
    OpenPath(PathBuf),
    Save,
    SaveAs,
    ExportRtf,
    ExportTxt,
    Close(usize),
    CloseAll,
    Quit,
    Undo,
    Redo,
    Cut,
    Copy,
    Paste,
    SelectAll,
    Dialog(Dialog),
    SetZoom(f32),
    ZoomMode(ZoomMode),
    ZoomIn,
    ZoomOut,
    Draft(bool),
    ToggleDark,
    PageBreak,
    InsertText(String),
    List(ListKind),
    Bold,
    Italic,
    Underline,
    Strike,
    Script(i8),
    Grow,
    Shrink,
    ClearFormat,
    Font(u8),
    Size(f32),
    Color([u8; 3]),
    Highlight(Option<[u8; 3]>),
    Align(Align),
    Indent(i8),
    Style(usize),
    Case(CaseChange),
    SelectTab(usize),
    NextTab,
    PageEdit(PageEdit),
    Toast(String),
}

#[derive(Clone, Copy, Debug)]
pub enum PageEdit {
    Size(f32, f32),
    Swap,
    Numbers(bool),
}

#[derive(Serialize, Deserialize, Clone)]
#[serde(default)]
pub struct Config {
    pub dark: bool,
    pub smartcorrect: bool,
    pub smart_quotes: bool,
    pub autosave_min: u32,
    pub recent: Vec<PathBuf>,
    pub margin_guides: bool,
    pub user_corrections: Vec<(String, String)>,
    pub removed_corrections: Vec<String>,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            dark: false,
            smartcorrect: true,
            smart_quotes: true,
            autosave_min: AUTOSAVE_MIN_DEFAULT,
            recent: Vec::new(),
            margin_guides: true,
            user_corrections: Vec::new(),
            removed_corrections: Vec::new(),
        }
    }
}

fn config_dir() -> Option<PathBuf> {
    dirs::config_dir().map(|d| d.join("ScribePro"))
}
pub fn recovery_dir() -> Option<PathBuf> {
    dirs::data_local_dir().map(|d| d.join("ScribePro").join("recovery"))
}

pub struct App {
    pub tabs: Vec<Tab>,
    pub active: usize,
    next_id: u64,
    untitled: usize,
    pub book: FontBook,
    pub zoom: f32,
    pub zoom_mode: ZoomMode,
    pub draft: bool,
    pub show_toolbar: bool,
    pub show_status: bool,
    pub show_ruler: bool,
    pub show_marks: bool,
    pub show_hf: bool,
    pub clean_screen: bool,
    pub cfg: Config,
    pub theme: Theme,
    pub sc_table: Vec<(String, String)>,
    pub dialog: Dialog,
    pub find: FindState,
    clip: Option<(String, Fragment)>,
    actions: Vec<Action>,
    screenshot: Option<PathBuf>,
    shot_done: Arc<AtomicBool>,
    frame: u64,
    toast: Option<(String, f64)>,
    last_autosave: f64,
    title: String,
    pub confirm_close: Option<usize>,
    pub confirm_quit: bool,
    force_quit: bool,
    pub doc_id: egui::Id,
    view_size: egui::Vec2,
    fonts_rev: u64,
}

impl App {
    pub fn new(cc: &eframe::CreationContext<'_>, screenshot: Option<PathBuf>, open: Vec<PathBuf>) -> Self {
        let book = fonts::install(&cc.egui_ctx);
        cc.egui_ctx.options_mut(|o| o.zoom_with_keyboard = false);
        let cfg = if screenshot.is_some() { Config::default() } else { load_config() };
        let theme = if cfg.dark { Theme::dark() } else { Theme::light() };
        theme.apply(&cc.egui_ctx);
        let mut app = Self {
            tabs: Vec::new(),
            active: 0,
            next_id: 1,
            untitled: 0,
            book,
            zoom: ZOOM_START,
            zoom_mode: ZoomMode::Percent,
            draft: false,
            show_toolbar: true,
            show_status: true,
            show_ruler: true,
            show_marks: false,
            show_hf: true,
            clean_screen: false,
            sc_table: Vec::new(),
            cfg,
            theme,
            dialog: Dialog::None,
            find: FindState::default(),
            clip: None,
            actions: Vec::new(),
            screenshot,
            shot_done: Arc::new(AtomicBool::new(false)),
            frame: 0,
            toast: None,
            last_autosave: 0.0,
            title: String::new(),
            confirm_close: None,
            confirm_quit: false,
            force_quit: false,
            doc_id: egui::Id::new("document-canvas"),
            view_size: vec2(1200.0, 800.0),
            fonts_rev: 1,
        };
        app.rebuild_sc_table();
        for p in open {
            app.open_path(&p);
        }
        if app.tabs.is_empty() {
            app.new_doc();
        }
        if app.screenshot.is_none() {
            if let Some(dir) = recovery_dir() {
                let found: Vec<PathBuf> = std::fs::read_dir(&dir)
                    .map(|rd| rd.filter_map(|e| e.ok().map(|e| e.path())).filter(|p| p.extension().map(|e| e == FILE_EXT).unwrap_or(false)).collect())
                    .unwrap_or_default();
                if !found.is_empty() {
                    app.dialog = Dialog::Recover(found);
                }
            }
        }
        cc.egui_ctx.memory_mut(|m| m.request_focus(app.doc_id));
        app
    }

    pub fn rebuild_sc_table(&mut self) {
        let mut t: Vec<(String, String)> = doc::smartcorrect_table().into_iter().filter(|(a, _)| !self.cfg.removed_corrections.contains(a)).collect();
        for (a, b) in &self.cfg.user_corrections {
            t.retain(|(x, _)| x != a);
            t.push((a.clone(), b.clone()));
        }
        self.sc_table = t;
    }

    pub fn save_config(&self) {
        if self.screenshot.is_some() {
            return;
        }
        if let Some(d) = config_dir() {
            let _ = std::fs::create_dir_all(&d);
            let _ = std::fs::write(d.join("settings.json"), serde_json::to_string_pretty(&self.cfg).unwrap_or_default());
        }
    }

    pub fn tab(&mut self) -> &mut Tab {
        let i = self.active.min(self.tabs.len() - 1);
        &mut self.tabs[i]
    }
    pub fn tab_ref(&self) -> &Tab {
        &self.tabs[self.active.min(self.tabs.len() - 1)]
    }

    fn new_doc(&mut self) {
        // "Untitled" + counter in base 10, as FUN_0044e7a6 builds it → "Untitled1"
        self.untitled += 1;
        let name = format!("Untitled{}", self.untitled);
        let t = Tab::new(self.next_id, name, Document::default());
        self.next_id += 1;
        self.tabs.push(t);
        self.active = self.tabs.len() - 1;
    }

    pub fn open_path(&mut self, path: &Path) {
        let ext = path.extension().map(|e| e.to_string_lossy().to_lowercase()).unwrap_or_default();
        let bytes = match std::fs::read(path) {
            Ok(b) => b,
            Err(e) => {
                self.toast(format!("Couldn't open {}: {e}", path.display()));
                return;
            }
        };
        let text = String::from_utf8_lossy(&bytes).to_string();
        let doc = match ext.as_str() {
            "wpx" => match doc::from_json(&text) {
                Ok(d) => d,
                Err(e) => {
                    self.toast(format!("That file isn't a readable document ({e})."));
                    return;
                }
            },
            "rtf" => doc::from_rtf(&text),
            "lwp" | "sam" | "mwp" => {
                self.toast("Files from the 1999 program use a closed format. Save them as Rich Text (RTF) there first.".into());
                return;
            }
            _ => doc::from_plain(&text),
        };
        // replace an untouched empty Untitled tab
        if self.tabs.len() == 1 && !self.tabs[0].dirty && self.tabs[0].path.is_none() && self.tabs[0].doc.plain_text().is_empty() {
            self.tabs.clear();
        }
        let mut t = Tab::new(self.next_id, path.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_else(|| "Document".into()), doc);
        self.next_id += 1;
        if ext == "wpx" || ext == "rtf" || ext == "txt" {
            t.path = Some(path.to_path_buf());
        }
        self.tabs.push(t);
        self.active = self.tabs.len() - 1;
        self.add_recent(path);
    }

    pub fn open_recovered(&mut self, path: &Path) {
        if let Ok(s) = std::fs::read_to_string(path) {
            if let Ok(d) = doc::from_json(&s) {
                self.untitled += 1;
                let mut t = Tab::new(self.next_id, format!("Recovered{}", self.untitled), d);
                self.next_id += 1;
                t.dirty = true;
                if self.tabs.len() == 1 && !self.tabs[0].dirty && self.tabs[0].doc.plain_text().is_empty() {
                    self.tabs.clear();
                }
                self.tabs.push(t);
                self.active = self.tabs.len() - 1;
            }
        }
        let _ = std::fs::remove_file(path);
    }

    fn add_recent(&mut self, path: &Path) {
        let p = path.to_path_buf();
        self.cfg.recent.retain(|r| r != &p);
        self.cfg.recent.insert(0, p);
        self.cfg.recent.truncate(8);
        self.save_config();
    }

    fn write_doc(doc: &Document, path: &Path) -> std::io::Result<()> {
        let ext = path.extension().map(|e| e.to_string_lossy().to_lowercase()).unwrap_or_default();
        let data = match ext.as_str() {
            "rtf" => doc::to_rtf(doc),
            "txt" => doc.plain_text().replace('\n', "\r\n"),
            _ => doc::to_json(doc),
        };
        std::fs::write(path, data)
    }

    pub fn save(&mut self, idx: usize, save_as: bool) -> bool {
        let path = if save_as || self.tabs[idx].path.is_none() {
            let base = self.tabs[idx].name.split('.').next().unwrap_or("Document").to_string();
            match rfd::FileDialog::new()
                .set_file_name(format!("{base}.{FILE_EXT}"))
                .add_filter("Scribe Pro document", &[FILE_EXT])
                .add_filter("Rich Text", &["rtf"])
                .add_filter("Plain text", &["txt"])
                .save_file()
            {
                Some(p) => p,
                None => return false,
            }
        } else {
            self.tabs[idx].path.clone().unwrap()
        };
        match Self::write_doc(&self.tabs[idx].doc, &path) {
            Ok(()) => {
                let t = &mut self.tabs[idx];
                t.path = Some(path.clone());
                t.name = path.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
                t.dirty = false;
                t.saved_rev = t.rev;
                let id = t.id;
                remove_recovery(id);
                self.add_recent(&path);
                self.toast(format!("Saved {}", path.display()));
                true
            }
            Err(e) => {
                self.toast(format!("Couldn't save: {e}"));
                false
            }
        }
    }

    fn export(&mut self, ext: &str) {
        let base = self.tab_ref().name.split('.').next().unwrap_or("Document").to_string();
        let filter = if ext == "rtf" { "Rich Text" } else { "Plain text" };
        if let Some(p) = rfd::FileDialog::new().set_file_name(format!("{base}.{ext}")).add_filter(filter, &[ext]).save_file() {
            match Self::write_doc(&self.tab_ref().doc, &p) {
                Ok(()) => self.toast(format!("Exported to {}", p.display())),
                Err(e) => self.toast(format!("Couldn't export: {e}")),
            }
        }
    }

    pub fn close_tab(&mut self, idx: usize, force: bool) {
        if idx >= self.tabs.len() {
            return;
        }
        if self.tabs[idx].dirty && !force {
            self.confirm_close = Some(idx);
            return;
        }
        remove_recovery(self.tabs[idx].id);
        self.tabs.remove(idx);
        if self.tabs.is_empty() {
            self.new_doc();
        }
        if idx < self.active {
            self.active -= 1;
        }
        self.active = self.active.min(self.tabs.len() - 1);
    }

    pub fn save_then_close(&mut self, idx: usize) {
        if self.save(idx, false) {
            self.close_tab(idx, true);
        }
    }

    pub fn toast(&mut self, msg: String) {
        self.toast = Some((msg, -1.0));
    }

    pub fn act(&mut self, a: Action) {
        self.actions.push(a);
    }

    pub fn effective_zoom(&self) -> f32 {
        let pg = self.tab_ref().doc.page;
        let w = (self.view_size.x - 2.0 * layout::PAGE_GAP - 16.0).max(100.0);
        let h = (self.view_size.y - 2.0 * layout::PAGE_GAP - 24.0).max(100.0);
        let z = match self.zoom_mode {
            ZoomMode::Percent => self.zoom,
            ZoomMode::PageWidth => w / (pg.width * BASE_PPI),
            ZoomMode::MarginWidth => w / ((pg.width - pg.margin_left - pg.margin_right + 0.4) * BASE_PPI),
            ZoomMode::FullPage => (w / (pg.width * BASE_PPI)).min(h / (pg.height * BASE_PPI)),
        };
        (z.clamp(ZOOM_MIN, ZOOM_MAX) * 100.0).round() / 100.0
    }

    fn run_actions(&mut self, ctx: &egui::Context) {
        let actions = std::mem::take(&mut self.actions);
        let now = ctx.input(|i| i.time);
        for a in actions {
            let mut refocus = true;
            match a {
                Action::New => self.new_doc(),
                Action::Open => {
                    if let Some(p) = rfd::FileDialog::new().add_filter("Documents", &[FILE_EXT, "rtf", "txt"]).add_filter("All files", &["*"]).pick_file() {
                        self.open_path(&p);
                    }
                }
                Action::OpenPath(p) => self.open_path(&p),
                Action::Save => {
                    let i = self.active;
                    self.save(i, false);
                }
                Action::SaveAs => {
                    let i = self.active;
                    self.save(i, true);
                }
                Action::ExportRtf => self.export("rtf"),
                Action::ExportTxt => self.export("txt"),
                Action::Close(i) => self.close_tab(i, false),
                Action::CloseAll => {
                    for i in (0..self.tabs.len()).rev() {
                        if !self.tabs[i].dirty {
                            self.close_tab(i, true);
                        }
                    }
                    if let Some(i) = self.tabs.iter().position(|t| t.dirty) {
                        self.active = i;
                        self.confirm_close = Some(i);
                    }
                }
                Action::Quit => ctx.send_viewport_cmd(egui::ViewportCommand::Close),
                Action::Undo => self.tab().undo(),
                Action::Redo => self.tab().redo(),
                Action::Cut | Action::Copy => {
                    let cut = matches!(a, Action::Cut);
                    let t = self.tab();
                    if let Some(c) = t.copy() {
                        ctx.copy_text(c.0.clone());
                        if cut {
                            t.checkpoint(EditKind::Other, now);
                            t.delete_selection();
                            t.changed();
                        }
                        self.clip = Some(c);
                    }
                }
                Action::Paste => ctx.send_viewport_cmd(egui::ViewportCommand::RequestPaste),
                Action::SelectAll => self.tab().select_all(),
                Action::Dialog(d) => {
                    if let Dialog::Find(replace) = d {
                        let sel = self.tab_ref().selected_text();
                        if !sel.is_empty() && !sel.contains('\n') && sel.chars().count() < 80 {
                            self.find.query = sel;
                        }
                        self.find.focus = true;
                        self.find.show_replace = replace;
                    }
                    self.dialog = d;
                    refocus = false;
                }
                Action::SetZoom(z) => {
                    self.zoom_mode = ZoomMode::Percent;
                    self.zoom = z.clamp(ZOOM_MIN, ZOOM_MAX);
                }
                Action::ZoomMode(m) => self.zoom_mode = m,
                Action::ZoomIn | Action::ZoomOut => {
                    let z = self.effective_zoom();
                    let steps = [0.25, 0.33, 0.5, 0.67, 0.75, 0.9, 1.0, 1.1, 1.25, 1.5, 1.75, 2.0];
                    let nz = if matches!(a, Action::ZoomIn) {
                        steps.iter().copied().find(|s| *s > z + 0.001).unwrap_or(ZOOM_MAX)
                    } else {
                        steps.iter().rev().copied().find(|s| *s < z - 0.001).unwrap_or(ZOOM_MIN)
                    };
                    self.zoom_mode = ZoomMode::Percent;
                    self.zoom = nz;
                }
                Action::Draft(d) => self.draft = d,
                Action::ToggleDark => {
                    self.cfg.dark = !self.cfg.dark;
                    self.theme = if self.cfg.dark { Theme::dark() } else { Theme::light() };
                    self.theme.apply(ctx);
                    self.save_config();
                }
                Action::PageBreak => self.tab().page_break(now),
                Action::InsertText(s) => self.tab().insert(&s, now),
                Action::List(k) => {
                    let t = self.tab();
                    let cur = t.doc.paras[t.doc.clamp(t.caret).p].fmt.list;
                    let nk = if cur == k { ListKind::None } else { k };
                    t.apply_para(now, &move |f| f.list = nk);
                }
                Action::Bold => self.tab().toggle(now, |s| s.bold, |s, v| s.bold = v),
                Action::Italic => self.tab().toggle(now, |s| s.italic, |s, v| s.italic = v),
                Action::Underline => self.tab().toggle(now, |s| s.underline, |s, v| s.underline = v),
                Action::Strike => self.tab().toggle(now, |s| s.strike, |s, v| s.strike = v),
                Action::Script(k) => {
                    let cur = self.tab_ref().typing_style().script;
                    let nk = if cur == k { 0 } else { k };
                    self.tab().apply_char(now, &move |s| s.script = nk);
                }
                Action::Grow => self.tab().apply_char(now, &|s| s.size = (s.size + SIZE_STEP).min(MAX_SIZE)),
                Action::Shrink => self.tab().apply_char(now, &|s| s.size = (s.size - SIZE_STEP).max(MIN_SIZE)),
                Action::ClearFormat => self.tab().clear_formatting(now),
                Action::Font(f) => self.tab().apply_char(now, &move |s| s.font = f),
                Action::Size(z) => self.tab().apply_char(now, &move |s| s.size = z.clamp(MIN_SIZE, MAX_SIZE)),
                Action::Color(c) => self.tab().apply_char(now, &move |s| s.color = c),
                Action::Highlight(h) => self.tab().apply_char(now, &move |s| s.highlight = h),
                Action::Align(al) => self.tab().apply_para(now, &move |f| f.align = al),
                Action::Indent(d) => self.tab().apply_para(now, &move |f| f.indent = (f.indent as i8 + d).clamp(0, 8) as u8),
                Action::Style(i) => self.tab().apply_named_style(i, now),
                Action::Case(k) => self.tab().change_case(k, now),
                Action::SelectTab(i) => self.active = i.min(self.tabs.len() - 1),
                Action::NextTab => self.active = (self.active + 1) % self.tabs.len(),
                Action::PageEdit(pe) => {
                    let t = self.tab();
                    t.checkpoint(EditKind::Other, now);
                    match pe {
                        PageEdit::Size(w, h) => {
                            t.doc.page.width = w;
                            t.doc.page.height = h;
                        }
                        PageEdit::Swap => {
                            let pg = &mut t.doc.page;
                            std::mem::swap(&mut pg.width, &mut pg.height);
                        }
                        PageEdit::Numbers(on) => t.doc.page.page_numbers = on,
                    }
                    t.changed();
                    t.scroll_to_caret = false;
                }
                Action::Toast(s) => self.toast(s),
            }
            if refocus {
                ctx.memory_mut(|m| m.request_focus(self.doc_id));
            }
        }
    }

    fn handle_cmds(&mut self, cmds: Vec<Cmd>) {
        for c in cmds {
            let a = match c {
                Cmd::New => Action::New,
                Cmd::Open => Action::Open,
                Cmd::Save => Action::Save,
                Cmd::SaveAs => Action::SaveAs,
                Cmd::Close => Action::Close(self.active),
                Cmd::Find => Action::Dialog(Dialog::Find(false)),
                Cmd::Replace => Action::Dialog(Dialog::Find(true)),
                Cmd::GoTo => Action::Dialog(Dialog::GoTo(self.tab_ref().current_page + 1)),
                Cmd::Print => Action::Toast("Printing isn't part of this version yet — export as Rich Text and print from another program.".into()),
                Cmd::Spell => Action::Toast("Spell checking isn't part of this version yet.".into()),
                Cmd::NextTab => Action::NextTab,
                Cmd::ZoomIn => Action::ZoomIn,
                Cmd::ZoomOut => Action::ZoomOut,
                Cmd::Zoom100 => Action::SetZoom(1.0),
                Cmd::WordCount => Action::Dialog(Dialog::WordCount),
            };
            self.actions.push(a);
        }
    }

    fn autosave(&mut self, now: f64) {
        if self.screenshot.is_some() || self.cfg.autosave_min == 0 {
            return;
        }
        if self.last_autosave == 0.0 {
            self.last_autosave = now.max(0.001);
            return;
        }
        if now - self.last_autosave < self.cfg.autosave_min as f64 * 60.0 {
            return;
        }
        self.last_autosave = now;
        let Some(dir) = recovery_dir() else { return };
        let _ = std::fs::create_dir_all(&dir);
        for t in &self.tabs {
            if t.dirty {
                let _ = std::fs::write(dir.join(format!("recovery-{}.{FILE_EXT}", t.id)), doc::to_json(&t.doc));
            }
        }
    }

    pub fn force_quit(&mut self, ctx: &egui::Context) {
        self.force_quit = true;
        ctx.send_viewport_cmd(egui::ViewportCommand::Close);
    }
}

fn load_config() -> Config {
    config_dir().and_then(|d| std::fs::read_to_string(d.join("settings.json")).ok()).and_then(|s| serde_json::from_str(&s).ok()).unwrap_or_default()
}

fn remove_recovery(id: u64) {
    if let Some(d) = recovery_dir() {
        let _ = std::fs::remove_file(d.join(format!("recovery-{id}.{FILE_EXT}")));
    }
}

