pub fn icon_button(ui: &mut egui::Ui, th: &Theme, icon: Icon, tip: &str, selected: bool, enabled: bool) -> egui::Response {
    let (rect, resp) = ui.allocate_exact_size(vec2(30.0, 30.0), if enabled { Sense::click() } else { Sense::hover() });
    let p = ui.painter();
    let bg = if selected {
        th.active
    } else if resp.hovered() && enabled {
        th.hover
    } else {
        Color32::TRANSPARENT
    };
    p.rect_filled(rect, 6.0, bg);
    let col = if !enabled {
        th.icon.gamma_multiply(0.35)
    } else if selected {
        th.accent
    } else {
        th.icon
    };
    let acc = if enabled { th.accent } else { th.accent.gamma_multiply(0.35) };
    icons::draw(p, rect.shrink(6.0), icon, col, acc);
    resp.on_hover_text(tip)
}

fn sep(ui: &mut egui::Ui, th: &Theme) {
    let (r, _) = ui.allocate_exact_size(vec2(9.0, 26.0), Sense::hover());
    ui.painter().line_segment([r.center_top() + vec2(0.0, 4.0), r.center_bottom() - vec2(0.0, 4.0)], Stroke::new(1.0, th.border));
}

