//! Loads the computer's own installed fonts (no downloads) so documents can use
//! real Times New Roman, Arial, etc. with true bold and italic faces.

use eframe::egui::{self, FontData, FontDefinitions, FontFamily};
use std::collections::HashMap;
use std::sync::Arc;

use crate::doc::FONT_NAMES;

/// Files for (regular, bold, italic, bold-italic).
fn files_for(name: &str) -> [&'static str; 4] {
    match name {
        "Times New Roman" => ["times.ttf", "timesbd.ttf", "timesi.ttf", "timesbi.ttf"],
        "Arial" => ["arial.ttf", "arialbd.ttf", "ariali.ttf", "arialbi.ttf"],
        "Calibri" => ["calibri.ttf", "calibrib.ttf", "calibrii.ttf", "calibriz.ttf"],
        "Cambria" => ["cambria.ttc", "cambriab.ttf", "cambriai.ttf", "cambriaz.ttf"],
        "Georgia" => ["georgia.ttf", "georgiab.ttf", "georgiai.ttf", "georgiaz.ttf"],
        "Garamond" => ["GARA.TTF", "GARABD.TTF", "GARAIT.TTF", ""],
        "Bookman Old Style" => ["BOOKOS.TTF", "BOOKOSB.TTF", "BOOKOSI.TTF", "BOOKOSBI.TTF"],
        "Palatino Linotype" => ["pala.ttf", "palab.ttf", "palai.ttf", "palabi.ttf"],
        "Segoe UI" => ["segoeui.ttf", "segoeuib.ttf", "segoeuii.ttf", "segoeuiz.ttf"],
        "Tahoma" => ["tahoma.ttf", "tahomabd.ttf", "", ""],
        "Trebuchet MS" => ["trebuc.ttf", "trebucbd.ttf", "trebucit.ttf", "trebucbi.ttf"],
        "Verdana" => ["verdana.ttf", "verdanab.ttf", "verdanai.ttf", "verdanaz.ttf"],
        "Courier New" => ["cour.ttf", "courbd.ttf", "couri.ttf", "courbi.ttf"],
        "Consolas" => ["consola.ttf", "consolab.ttf", "consolai.ttf", "consolaz.ttf"],
        _ => ["", "", "", ""],
    }
}

/// Which faces actually exist, so the layout knows when to fake italics.
#[derive(Default, Clone)]
pub struct FontBook {
    /// key: (font index, variant 0..4) → egui family name, or None when missing.
    pub faces: HashMap<(u8, u8), Option<String>>,
    pub ui_loaded: bool,
}

impl FontBook {
    /// Returns the family to use and whether italics must be synthesised.
    pub fn family(&self, font: u8, bold: bool, italic: bool) -> (FontFamily, bool) {
        let v = (bold as u8) | ((italic as u8) << 1);
        if let Some(Some(name)) = self.faces.get(&(font, v)) {
            return (FontFamily::Name(name.clone().into()), false);
        }
        // try without italic (fake it), then without bold
        if italic {
            if let Some(Some(name)) = self.faces.get(&(font, bold as u8)) {
                return (FontFamily::Name(name.clone().into()), true);
            }
        }
        if let Some(Some(name)) = self.faces.get(&(font, 0)) {
            return (FontFamily::Name(name.clone().into()), italic);
        }
        if font != 0 {
            return self.family(0, bold, italic);
        }
        (FontFamily::Proportional, italic)
    }
}

fn font_dir() -> std::path::PathBuf {
    let windir = std::env::var("WINDIR").unwrap_or_else(|_| "C:\\Windows".into());
    std::path::Path::new(&windir).join("Fonts")
}

pub fn install(ctx: &egui::Context) -> FontBook {
    let mut defs = FontDefinitions::default();
    let mut book = FontBook::default();
    let dir = font_dir();

    let load = |file: &str| -> Option<FontData> {
        if file.is_empty() {
            return None;
        }
        std::fs::read(dir.join(file)).ok().map(FontData::from_owned)
    };

    // Symbol fallback for bullets, arrows and other special characters.
    let mut fallbacks: Vec<String> = Vec::new();
    for (key, file) in [("sym:segoe-symbol", "seguisym.ttf"), ("sym:segoe-ui", "segoeui.ttf")] {
        if let Some(d) = load(file) {
            defs.font_data.insert(key.into(), Arc::new(d));
            fallbacks.push(key.into());
        }
    }
    let egui_defaults: Vec<String> = defs.families.get(&FontFamily::Proportional).cloned().unwrap_or_default();

    for (fi, name) in FONT_NAMES.iter().enumerate() {
        let files = files_for(name);
        for v in 0..4u8 {
            let key = format!("{name}#{v}");
            match load(files[v as usize]) {
                Some(data) => {
                    defs.font_data.insert(key.clone(), Arc::new(data));
                    let mut chain = vec![key.clone()];
                    chain.extend(fallbacks.iter().cloned());
                    chain.extend(egui_defaults.iter().cloned());
                    defs.families.insert(FontFamily::Name(key.clone().into()), chain);
                    book.faces.insert((fi as u8, v), Some(key));
                }
                None => {
                    book.faces.insert((fi as u8, v), None);
                }
            }
        }
    }

    // Modern UI font: Segoe UI when present.
    if let Some(d) = load("segoeui.ttf") {
        defs.font_data.insert("ui:segoe".into(), Arc::new(d));
        if let Some(list) = defs.families.get_mut(&FontFamily::Proportional) {
            list.insert(0, "ui:segoe".into());
        }
        book.ui_loaded = true;
    }
    if let Some(d) = load("segoeuib.ttf") {
        defs.font_data.insert("ui:segoe-bold".into(), Arc::new(d));
        let mut chain = vec!["ui:segoe-bold".to_string()];
        chain.extend(egui_defaults.iter().cloned());
        defs.families.insert(FontFamily::Name("ui-bold".into()), chain);
    } else {
        defs.families.insert(FontFamily::Name("ui-bold".into()), egui_defaults.clone());
    }
    for f in &fallbacks {
        if let Some(list) = defs.families.get_mut(&FontFamily::Proportional) {
            list.push(f.clone());
        }
    }
    ctx.set_fonts(defs);
    book
}

//! Turns the document into positioned lines on pages.

use eframe::egui::{
    self,
    text::{LayoutJob, LayoutSection, TextFormat, TextWrapping},
    Color32, FontId, Galley, Pos2, Rect, Stroke, Vec2,
};
use std::sync::Arc;

use crate::doc::{Align, CharStyle, Document, ListKind};
use crate::fonts::FontBook;

/// egui points per inch at 100 % zoom.
pub const BASE_PPI: f32 = 96.0;
/// Gap between pages on screen (points, not zoomed).
pub const PAGE_GAP: f32 = 28.0;
/// Hanging indent for bullets and numbers, in inches.
pub const LIST_HANG: f32 = 0.25;
/// One indent level, in inches.
pub const INDENT_STEP: f32 = 0.5;

#[derive(Clone)]
pub struct Line {
    pub para: usize,
    pub start: usize,
    pub end: usize,
    pub page: usize,
    /// Position of the line's left edge relative to the page's content box.
    pub x: f32,
    pub y: f32,
    pub height: f32,
    pub galley: Arc<Galley>,
    /// x of each char boundary (len = end - start + 1), relative to `x`.
    pub xs: Vec<f32>,
    pub last_in_para: bool,
    pub marker: Option<Arc<Galley>>,
    pub marker_x: f32,
}

pub struct PageLayout {
    pub lines: Vec<Line>,
    pub pages: usize,
    pub ppi: f32,
    pub page_size: Vec2,
    pub content_offset: Vec2,
    pub content_size: Vec2,
    pub draft: bool,
}

pub fn color(c: [u8; 3]) -> Color32 {
    Color32::from_rgb(c[0], c[1], c[2])
}

pub fn text_format(book: &FontBook, s: &CharStyle, ppi: f32) -> TextFormat {
    let (family, fake_italic) = book.family(s.font, s.bold, s.italic);
    let mut size = s.size * ppi / 72.0;
    if s.script != 0 {
        size *= 0.65;
    }
    let col = color(s.color);
    let line_w = (size / 16.0).max(1.0);
    TextFormat {
        font_id: FontId::new(size.max(1.0), family),
        color: col,
        background: s.highlight.map(color).unwrap_or(Color32::TRANSPARENT),
        italics: fake_italic,
        underline: if s.underline { Stroke::new(line_w, col) } else { Stroke::NONE },
        strikethrough: if s.strike { Stroke::new(line_w, col) } else { Stroke::NONE },
        valign: if s.script > 0 { egui::Align::TOP } else { egui::Align::BOTTOM },
        ..Default::default()
    }
}

fn single_row(galley: &Arc<Galley>, row: usize) -> Arc<Galley> {
    let mut g: Galley = (**galley).clone();
    let mut placed = g.rows[row].clone();
    placed.pos = Pos2::new(0.0, 0.0);
    let size = placed.row.size;
    let mesh_bounds = placed.row.visuals.mesh_bounds;
    g.num_vertices = placed.row.visuals.mesh.vertices.len();
    g.num_indices = placed.row.visuals.mesh.indices.len();
    placed.ends_with_newline = false;
    g.rows = vec![placed];
    g.rect = Rect::from_min_size(Pos2::ZERO, size);
    g.mesh_bounds = mesh_bounds;
    Arc::new(g)
}

pub fn build(ctx: &egui::Context, doc: &Document, book: &FontBook, zoom: f32, draft: bool) -> PageLayout {
    let ppi = BASE_PPI * zoom;
    let pg = &doc.page;
    let page_size = Vec2::new(pg.width * ppi, pg.height * ppi);
    let (content_offset, content_size) = if draft {
        (Vec2::new(0.5 * ppi, 0.4 * ppi), Vec2::new((pg.width - pg.margin_left - pg.margin_right) * ppi, f32::INFINITY))
    } else {
        (
            Vec2::new(pg.margin_left * ppi, pg.margin_top * ppi),
            Vec2::new((pg.width - pg.margin_left - pg.margin_right) * ppi, (pg.height - pg.margin_top - pg.margin_bottom) * ppi),
        )
    };
    let pt = ppi / 72.0;
    let mut lines: Vec<Line> = Vec::new();
    let mut page = 0usize;
    let mut y = 0.0f32;

    ctx.fonts_mut(|fonts| {
        for (pi, para) in doc.paras.iter().enumerate() {
            let fmt = para.fmt;
            if fmt.page_break_before && pi > 0 && !draft {
                page += 1;
                y = 0.0;
            }
            if y > 0.0 {
                y += fmt.space_before * pt;
            }
            let hang = if fmt.list != ListKind::None { LIST_HANG * ppi } else { 0.0 };
            let indent = fmt.indent as f32 * INDENT_STEP * ppi + hang;
            let avail = (content_size.x - indent).max(20.0);

            let mut job = LayoutJob::default();
            let empty = para.text.is_empty();
            if empty {
                job.append(" ", 0.0, text_format(book, &para.end_style, ppi));
            } else {
                for (a, b, s) in para.runs() {
                    let text: String = para.text[a..b].iter().collect();
                    let start = job.text.len();
                    job.text.push_str(&text);
                    job.sections.push(LayoutSection { leading_space: 0.0, byte_range: start..job.text.len(), format: text_format(book, &s, ppi) });
                }
            }
            job.wrap = TextWrapping { max_width: avail, ..Default::default() };
            job.justify = fmt.align == Align::Justify;
            job.keep_trailing_whitespace = true;
            let galley = fonts.layout_job(job);

            // marker for bullets / numbers
            let marker = if fmt.list != ListKind::None {
                let s = para.style_at(0);
                let text = match fmt.list {
                    ListKind::Bullet => ["•", "◦", "▪"][(fmt.indent as usize) % 3].to_string(),
                    _ => format!("{}.", doc.list_number(pi)),
                };
                let mut mj = LayoutJob::default();
                mj.append(&text, 0.0, text_format(book, &CharStyle { underline: false, strike: false, highlight: None, ..s }, ppi));
                Some(fonts.layout_job(mj))
            } else {
                None
            };

            let nrows = galley.rows.len();
            let mut char_cursor = 0usize;
            for r in 0..nrows {
                let placed = &galley.rows[r];
                let glyphs = &placed.row.glyphs;
                let count = if empty { 0 } else { glyphs.len() };
                let start = char_cursor.min(para.len());
                let end = (char_cursor + count).min(para.len());
                char_cursor += count;
                // trimmed row width for alignment
                let mut trimmed = 0.0f32;
                for g in glyphs.iter().rev() {
                    if !g.chr.is_whitespace() {
                        trimmed = g.pos.x + g.advance_width;
                        break;
                    }
                }
                let offset = match fmt.align {
                    Align::Left | Align::Justify => 0.0,
                    Align::Center => ((avail - trimmed) / 2.0).max(0.0),
                    Align::Right => (avail - trimmed).max(0.0),
                };
                let mut xs = Vec::with_capacity(end - start + 1);
                for k in 0..(end - start) {
                    xs.push(offset + glyphs.get(k).map(|g| g.pos.x).unwrap_or(0.0));
                }
                let end_x = if end > start {
                    glyphs.get(end - start - 1).map(|g| g.pos.x + g.advance_width).unwrap_or(0.0)
                } else {
                    0.0
                };
                xs.push(offset + end_x);
                let h = placed.row.size.y.max(1.0) * fmt.line_spacing;
                if !draft && y + h > content_size.y && y > 0.0 {
                    page += 1;
                    y = 0.0;
                }
                lines.push(Line {
                    para: pi,
                    start,
                    end,
                    page,
                    x: indent + offset,
                    y,
                    height: h,
                    galley: single_row(&galley, r),
                    xs: xs.iter().map(|v| v - offset).collect(),
                    last_in_para: r + 1 == nrows,
                    marker: if r == 0 { marker.clone() } else { None },
                    marker_x: indent - hang,
                });
                y += h;
            }
            y += fmt.space_after * pt;
        }
    });

    let pages = page + 1;
    let page_size = if draft { Vec2::new(page_size.x, (y + content_offset.y * 2.0).max(page_size.y)) } else { page_size };
    PageLayout { lines, pages, ppi, page_size, content_offset, content_size, draft }
}

impl PageLayout {
    /// Top-left of page `k` relative to the document canvas origin.
    pub fn page_origin(&self, k: usize, canvas_w: f32) -> Pos2 {
        let x = ((canvas_w - self.page_size.x) / 2.0).max(PAGE_GAP);
        Pos2::new(x, PAGE_GAP + k as f32 * (self.page_size.y + PAGE_GAP))
    }
    pub fn canvas_size(&self, min_w: f32) -> Vec2 {
        Vec2::new((self.page_size.x + 2.0 * PAGE_GAP).max(min_w), PAGE_GAP + self.pages as f32 * (self.page_size.y + PAGE_GAP))
    }
    pub fn line_origin(&self, line: &Line, canvas_min: Pos2, canvas_w: f32) -> Pos2 {
        let po = self.page_origin(line.page, canvas_w);
        canvas_min + po.to_vec2() + self.content_offset + Vec2::new(line.x, line.y)
    }
    /// Index of the line containing doc position (para, c).
    pub fn line_of(&self, p: usize, c: usize) -> usize {
        // binary search for first line of para
        let first = self.lines.partition_point(|l| l.para < p);
        let mut i = first;
        while i < self.lines.len() && self.lines[i].para == p {
            let l = &self.lines[i];
            if c < l.end || l.last_in_para || (c == l.end && i + 1 < self.lines.len() && self.lines[i + 1].para != p) {
                return i;
            }
            i += 1;
        }
        first.min(self.lines.len().saturating_sub(1))
    }
    pub fn x_in_line(&self, li: usize, c: usize) -> f32 {
        let l = &self.lines[li];
        let k = c.saturating_sub(l.start).min(l.xs.len() - 1);
        l.x + l.xs[k]
    }
    /// Char index nearest to x (relative to content box) in a line.
    pub fn char_at_x(&self, li: usize, x: f32) -> usize {
        let l = &self.lines[li];
        let rel = x - l.x;
        let n = l.end - l.start;
        for k in 0..n {
            let mid = (l.xs[k] + l.xs[k + 1]) / 2.0;
            if rel < mid {
                return l.start + k;
            }
        }
        // don't place caret after the trailing space of a wrapped line
        if !l.last_in_para && n > 0 {
            return l.end - 1;
        }
        l.end
    }
}

//! Flat, line-style toolbar icons drawn as vector shapes (no bitmaps).

use eframe::egui::{epaint::CubicBezierShape, pos2, vec2, Color32, FontFamily, FontId, Painter, Pos2, Rect, Shape, Stroke};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Icon {
    New,
    Open,
    Save,
    Export,
    Undo,
    Redo,
    Cut,
    Copy,
    Paste,
    Find,
    Bold,
    Italic,
    Underline,
    Strike,
    TextColor,
    Highlight,
    AlignLeft,
    AlignCenter,
    AlignRight,
    AlignJustify,
    Bullets,
    Numbers,
    Outdent,
    Indent,
    PageBreak,
    DateTime,
    Symbol,
    Marks,
    ZoomIn,
    ZoomOut,
    FullPage,
    PageWidth,
    WordCount,
    PageSetup,
    Styles,
    Clear,
    Superscript,
    Subscript,
    Grow,
    Shrink,
    Moon,
    Sun,
    Close,
}

pub fn draw(p: &Painter, r: Rect, icon: Icon, col: Color32, accent: Color32) {
    let s = r.width().min(r.height());
    let c = r.center();
    let u = s / 20.0; // design grid: 20 × 20
    let at = |x: f32, y: f32| -> Pos2 { pos2(c.x + (x - 10.0) * u, c.y + (y - 10.0) * u) };
    let st = Stroke::new(1.5 * u.max(0.8), col);
    let acc = Stroke::new(1.5 * u.max(0.8), accent);
    let line = |a: (f32, f32), b: (f32, f32), stroke: Stroke| p.line_segment([at(a.0, a.1), at(b.0, b.1)], stroke);
    let poly = |pts: &[(f32, f32)], stroke: Stroke, closed: bool| {
        let v: Vec<Pos2> = pts.iter().map(|q| at(q.0, q.1)).collect();
        if closed {
            p.add(Shape::closed_line(v, stroke));
        } else {
            p.add(Shape::line(v, stroke));
        }
    };
    let rrect = |x0: f32, y0: f32, x1: f32, y1: f32, rad: f32, stroke: Stroke| {
        p.rect_stroke(Rect::from_min_max(at(x0, y0), at(x1, y1)), rad * u, stroke, eframe::egui::StrokeKind::Middle);
    };
    let text = |t: &str, size: f32, color: Color32, family: FontFamily, dy: f32| {
        p.text(at(10.0, 10.0 + dy), eframe::egui::Align2::CENTER_CENTER, t, FontId::new(size * u, family), color);
    };
    let lines_icon = |xs: [(f32, f32); 4]| {
        for (i, (a, b)) in xs.iter().enumerate() {
            let yy = 4.5 + i as f32 * 3.7;
            line((*a, yy), (*b, yy), st);
        }
    };
    let arc = |cx: f32, cy: f32, rad: f32, a0: f32, a1: f32, stroke: Stroke| {
        let n = 18;
        let pts: Vec<Pos2> = (0..=n)
            .map(|i| {
                let t = a0 + (a1 - a0) * i as f32 / n as f32;
                at(cx + rad * t.cos(), cy + rad * t.sin())
            })
            .collect();
        p.add(Shape::line(pts, stroke));
    };
    match icon {
        Icon::New => {
            poly(&[(5.0, 2.5), (11.5, 2.5), (15.5, 6.5), (15.5, 17.5), (5.0, 17.5)], st, true);
            poly(&[(11.5, 2.5), (11.5, 6.5), (15.5, 6.5)], st, false);
            line((10.25, 9.0), (10.25, 15.0), acc);
            line((7.25, 12.0), (13.25, 12.0), acc);
        }
        Icon::Open => {
            poly(&[(2.5, 5.0), (7.5, 5.0), (9.0, 6.5), (15.5, 6.5), (15.5, 8.5)], st, false);
            poly(&[(2.5, 5.0), (2.5, 16.0), (15.0, 16.0), (17.5, 9.0), (5.0, 9.0), (2.5, 16.0)], st, false);
            p.add(Shape::convex_polygon(
                vec![at(5.4, 9.8), at(16.4, 9.8), at(14.4, 15.2), at(3.6, 15.2)],
                accent.gamma_multiply(0.25),
                Stroke::NONE,
            ));
        }
        Icon::Save => {
            poly(&[(3.0, 3.0), (14.0, 3.0), (17.0, 6.0), (17.0, 17.0), (3.0, 17.0)], st, true);
            rrect(6.0, 3.0, 13.0, 7.5, 0.5, st);
            rrect(6.0, 11.0, 14.0, 17.0, 0.5, acc);
        }
        Icon::Export => {
            poly(&[(5.0, 8.0), (3.0, 8.0), (3.0, 17.0), (17.0, 17.0), (17.0, 8.0), (15.0, 8.0)], st, false);
            line((10.0, 2.5), (10.0, 12.5), acc);
            poly(&[(6.5, 6.0), (10.0, 2.5), (13.5, 6.0)], acc, false);
        }
        Icon::Undo => {
            arc(11.0, 11.0, 5.5, -std::f32::consts::FRAC_PI_2 * 1.0, std::f32::consts::FRAC_PI_2, st);
            line((11.0, 5.5), (4.5, 5.5), st);
            poly(&[(7.5, 2.5), (4.5, 5.5), (7.5, 8.5)], st, false);
            line((11.0, 16.5), (7.0, 16.5), st);
        }
        Icon::Redo => {
            arc(9.0, 11.0, 5.5, std::f32::consts::FRAC_PI_2, std::f32::consts::PI * 1.5, st);
            line((9.0, 5.5), (15.5, 5.5), st);
            poly(&[(12.5, 2.5), (15.5, 5.5), (12.5, 8.5)], st, false);
            line((9.0, 16.5), (13.0, 16.5), st);
        }
        Icon::Cut => {
            p.circle_stroke(at(6.0, 14.5), 2.6 * u, st);
            p.circle_stroke(at(14.0, 14.5), 2.6 * u, st);
            line((7.6, 12.5), (14.0, 2.5), st);
            line((12.4, 12.5), (6.0, 2.5), st);
