        }
        Icon::Outdent | Icon::Indent => {
            line((3.0, 4.0), (17.0, 4.0), st);
            line((9.0, 8.0), (17.0, 8.0), st);
            line((9.0, 12.0), (17.0, 12.0), st);
            line((3.0, 16.0), (17.0, 16.0), st);
            if icon == Icon::Indent {
                poly(&[(3.0, 7.0), (6.0, 10.0), (3.0, 13.0)], acc, false);
