        Icon::PageBreak => {
            poly(&[(4.0, 2.5), (4.0, 7.0), (16.0, 7.0), (16.0, 2.5)], st, false);
            poly(&[(4.0, 17.5), (4.0, 13.0), (16.0, 13.0), (16.0, 17.5)], st, false);
            for i in 0..4 {
                let x = 2.5 + i as f32 * 4.5;
