impl eframe::App for App {
    fn ui(&mut self, ui: &mut egui::Ui, _frame: &mut eframe::Frame) {
        let ctx = ui.ctx().clone();
        self.frame += 1;
        let now = ctx.input(|i| i.time);

        // screenshot mode: draw ~120 frames, save the picture, exit
        if let Some(path) = self.screenshot.clone() {
            ctx.request_repaint();
            if self.frame == 120 {
                let done = self.shot_done.clone();
                ctx.request_screenshot(move |img| {
                    let [w, h] = img.size;
                    let mut buf = Vec::with_capacity(w * h * 4);
                    for p in &img.pixels {
                        buf.extend_from_slice(&[p.r(), p.g(), p.b(), 255]);
                    }
                    if let Some(parent) = path.parent() {
                        let _ = std::fs::create_dir_all(parent);
                    }
                    if let Some(im) = image::RgbaImage::from_raw(w as u32, h as u32, buf) {
                        let _ = im.save(&path);
                    }
                    done.store(true, Ordering::SeqCst);
                });
            }
            if self.shot_done.load(Ordering::SeqCst) || self.frame > 600 {
                ctx.send_viewport_cmd(egui::ViewportCommand::Close);
            }
        }

        // closing the window with unsaved work
        if ctx.input(|i| i.viewport().close_requested()) && !self.force_quit && self.tabs.iter().any(|t| t.dirty) {
            ctx.send_viewport_cmd(egui::ViewportCommand::CancelClose);
            self.confirm_quit = true;
        }

        // window title, like "Word Pro - [Untitled1]"
        let title = format!("{APP_NAME} - [{}]", self.tab_ref().title());
        if title != self.title {
            ctx.send_viewport_cmd(egui::ViewportCommand::Title(title.clone()));
            self.title = title;
        }

        let th = self.theme.clone();

        // ── menu bar ──
        egui::Panel::top("menubar").frame(Frame::new().fill(th.chrome).inner_margin(Margin::symmetric(6, 2))).show(ui, |ui| {
            egui::MenuBar::new().ui(ui, |ui| {
                self.menus(ui);
            });
        });

        // ── toolbar ──
        if self.show_toolbar && !self.clean_screen {
            egui::Panel::top("toolbar")
                .frame(Frame::new().fill(th.toolbar).inner_margin(Margin::symmetric(8, 4)).stroke(Stroke::new(1.0, th.border)))
                .show(ui, |ui| {
                    ui.horizontal_wrapped(|ui| {
                        ui.spacing_mut().item_spacing.x = 2.0;
                        self.toolbar(ui, &th);
                    });
                });
        }

        // ── tabs ──
        if !self.clean_screen {
            egui::Panel::top("tabs").frame(Frame::new().fill(th.chrome).inner_margin(Margin { left: 8, right: 8, top: 4, bottom: 0 })).show(ui, |ui| {
                self.tab_strip(ui, &th);
            });
        }

        // ── status bar ──
        if self.show_status && !self.clean_screen {
            egui::Panel::bottom("status")
                .frame(Frame::new().fill(th.chrome).inner_margin(Margin::symmetric(10, 3)).stroke(Stroke::new(1.0, th.border)))
                .show(ui, |ui| {
                    self.status_bar(ui, &th);
                });
        }

        // ── document ──
        let mut cmds = Vec::new();
        egui::CentralPanel::default().frame(Frame::new().fill(th.workspace)).show(ui, |ui| {
            let full = ui.available_rect_before_wrap();
            self.view_size = full.size();
            let zoom = self.effective_zoom();
            if self.show_ruler && !self.clean_screen && !self.draft {
                self.ruler(ui, &th, zoom);
            }
            // ctrl + wheel zooms the page
            let zd = ui.input(|i| i.zoom_delta());
            if zd != 1.0 && ui.rect_contains_pointer(full) {
                self.zoom_mode = ZoomMode::Percent;
                self.zoom = (zoom * zd).clamp(ZOOM_MIN, ZOOM_MAX);
            }
            let zoom = self.effective_zoom();
            let draft = self.draft;
            let show_marks = self.show_marks;
            let guides = self.cfg.margin_guides;
            let show_hf = self.show_hf;
            let doc_id = self.doc_id;
            let book = self.book.clone();
            let fonts_rev = self.fonts_rev;
            let matches = if matches!(self.dialog, Dialog::Find(_)) { self.find.matches(&self.tabs[self.active].doc, self.tabs[self.active].rev) } else { Vec::new() };
            let table = std::mem::take(&mut self.sc_table);
            let sc = SmartCorrect { enabled: self.cfg.smartcorrect, quotes: self.cfg.smart_quotes, table: &table };
            let focused = ui.memory(|m| m.focused());
            let doc_has_keys = focused.is_none() || focused == Some(doc_id);
            let view_h = ui.available_height();
            let active = self.active;
            let tab_id = self.tabs[active].id;
            let mut clip = self.clip.take();
            {
                let tab = &mut self.tabs[active];
                let opts = ViewOpts { zoom, draft, show_marks, margin_guides: guides, header_footer: show_hf, matches: &matches, theme: &th, book: &book, fonts_rev };
                if doc_has_keys {
                    let lay = tab.layout(&ctx, &opts);
                    tab.handle_keys(ui, &lay, &sc, &mut clip, &mut cmds, view_h);
                }
                let out = egui::ScrollArea::both().id_salt(("doc", tab_id)).auto_shrink([false, false]).show(ui, |ui| {
                    tab.show(ui, &opts, doc_id)
                });
                tab.h_offset = out.state.offset.x;
            }
            self.clip = clip;
            self.sc_table = table;
            if doc_has_keys && focused.is_none() {
                ui.memory_mut(|m| m.request_focus(doc_id));
            }
        });
        ui.memory_mut(|m| {
            m.set_focus_lock_filter(self.doc_id, egui::EventFilter { tab: true, horizontal_arrows: true, vertical_arrows: true, escape: false });
        });
        self.handle_cmds(cmds);

        // dialogs
        dialogs::show(self, &ctx);

        // toast
        if let Some((msg, t0)) = self.toast.clone() {
            let t0 = if t0 < 0.0 { now } else { t0 };
            self.toast = Some((msg.clone(), t0));
            if now - t0 > 4.0 {
                self.toast = None;
            } else {
                egui::Area::new(egui::Id::new("toast")).anchor(egui::Align2::CENTER_BOTTOM, vec2(0.0, -48.0)).show(&ctx, |ui| {
                    Frame::new().fill(Color32::from_rgb(31, 41, 55)).corner_radius(8).inner_margin(Margin::symmetric(14, 8)).show(ui, |ui| {
                        ui.label(RichText::new(msg).color(Color32::WHITE));
                    });
                });
                ctx.request_repaint_after(std::time::Duration::from_millis(250));
            }
        }

        self.run_actions(&ctx);
        self.autosave(now);
    }

    fn on_exit(&mut self) {
        // a normal exit leaves no recovery files behind
        if self.screenshot.is_none() {
            for t in &self.tabs {
                remove_recovery(t.id);
            }
        }
    }
}

impl App {
    pub fn force_quit(&mut self, ctx: &egui::Context) {
        self.force_quit = true;
        ctx.send_viewport_cmd(egui::ViewportCommand::Close);
    }

    // ───── menus (names and order from the original's menu resource 1002) ─────
    fn menus(&mut self, ui: &mut egui::Ui) {
        let item = |ui: &mut egui::Ui, label: &str, sc: &str| -> bool {
            let b = if sc.is_empty() { egui::Button::new(label) } else { egui::Button::new(label).shortcut_text(sc) };
            ui.add(b).clicked()
        };
        let has_sel = self.tab_ref().has_selection();
        let can_undo = self.tab_ref().can_undo();
        let can_redo = self.tab_ref().can_redo();

        ui.menu_button("File", |ui| {
            if item(ui, "New Document", "Ctrl+N") {
                self.act(Action::New);
            }
            if item(ui, "Open…", "Ctrl+O") {
                self.act(Action::Open);
            }
            if item(ui, "Close", "Ctrl+W") {
                let i = self.active;
                self.act(Action::Close(i));
            }
            ui.separator();
            if item(ui, "Save", "Ctrl+S") {
                self.act(Action::Save);
            }
            if item(ui, "Save As…", "Ctrl+Shift+S") {
                self.act(Action::SaveAs);
            }
            ui.menu_button("Export", |ui| {
                if item(ui, "Rich Text (.rtf)…", "") {
                    self.act(Action::ExportRtf);
                }
                if item(ui, "Plain Text (.txt)…", "") {
                    self.act(Action::ExportTxt);
                }
            });
            ui.separator();
            ui.menu_button("Document Properties", |ui| {
                if item(ui, "Document…", "") {
                    self.act(Action::Dialog(Dialog::DocProps));
                }
                if item(ui, "Page Setup…", "") {
                    self.act(Action::Dialog(Dialog::PageSetup));
                }
            });
            ui.menu_button("User Setup", |ui| {
                if item(ui, "Preferences…", "") {
                    self.act(Action::Dialog(Dialog::Prefs));
                }
                if item(ui, "SmartCorrect Setup…", "") {
                    self.act(Action::Dialog(Dialog::SmartCorrect(String::new(), String::new())));
                }
            });
            if !self.cfg.recent.is_empty() {
                ui.separator();
                ui.label(RichText::new("Recent documents").small().weak());
                for (i, p) in self.cfg.recent.clone().iter().enumerate() {
                    let name = p.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
                    if ui.add(egui::Button::new(format!("{}  {}", i + 1, name))).on_hover_text(p.display().to_string()).clicked() {
                        self.act(Action::OpenPath(p.clone()));
                    }
                }
            }
            ui.separator();
            if item(ui, "Exit", "Alt+F4") {
                self.act(Action::Quit);
            }
        });

        ui.menu_button("Edit", |ui| {
            if ui.add_enabled(can_undo, egui::Button::new("Undo").shortcut_text("Ctrl+Z")).clicked() {
                self.act(Action::Undo);
            }
            if ui.add_enabled(can_redo, egui::Button::new("Redo").shortcut_text("Ctrl+Y")).clicked() {
                self.act(Action::Redo);
            }
            ui.separator();
            if ui.add_enabled(has_sel, egui::Button::new("Cut").shortcut_text("Ctrl+X")).clicked() {
                self.act(Action::Cut);
            }
            if ui.add_enabled(has_sel, egui::Button::new("Copy").shortcut_text("Ctrl+C")).clicked() {
                self.act(Action::Copy);
            }
            if item(ui, "Paste", "Ctrl+V") {
                self.act(Action::Paste);
            }
            if item(ui, "Select All", "Ctrl+A") {
                self.act(Action::SelectAll);
            }
            ui.separator();
            if item(ui, "Go To…", "Ctrl+G") {
                let p = self.tab_ref().current_page + 1;
                self.act(Action::Dialog(Dialog::GoTo(p)));
            }
            if item(ui, "Find & Replace Text…", "Ctrl+F") {
                self.act(Action::Dialog(Dialog::Find(true)));
            }
            ui.menu_button("Proofing Tools", |ui| {
                if item(ui, "Quick Find…", "Ctrl+F") {
                    self.act(Action::Dialog(Dialog::Find(false)));
                }
                if item(ui, "Word Count…", "") {
                    self.act(Action::Dialog(Dialog::WordCount));
                }
                ui.separator();
                let mut on = self.cfg.smartcorrect;
                if ui.checkbox(&mut on, "SmartCorrect while typing").changed() {
                    self.cfg.smartcorrect = on;
                    self.save_config();
                }
            });
        });

        ui.menu_button("View", |ui| {
            if ui.add(egui::Button::new("Layout").selected(!self.draft)).clicked() {
                self.act(Action::Draft(false));
            }
            if ui.add(egui::Button::new("Draft").selected(self.draft)).clicked() {
                self.act(Action::Draft(true));
            }
            ui.separator();
            if ui.add(egui::Button::new("Full Page").selected(self.zoom_mode == ZoomMode::FullPage)).clicked() {
                self.act(Action::ZoomMode(ZoomMode::FullPage));
            }
            if ui.add(egui::Button::new("Standard (100%)").shortcut_text("Ctrl+0").selected(self.zoom_mode == ZoomMode::Percent && self.zoom == 1.0)).clicked() {
                self.act(Action::SetZoom(1.0));
            }
            ui.menu_button("Zoom To", |ui| {
                if ui.add(egui::Button::new("Margin Width").selected(self.zoom_mode == ZoomMode::MarginWidth)).clicked() {
                    self.act(Action::ZoomMode(ZoomMode::MarginWidth));
                }
                if ui.add(egui::Button::new("Page Width").selected(self.zoom_mode == ZoomMode::PageWidth)).clicked() {
                    self.act(Action::ZoomMode(ZoomMode::PageWidth));
                }
                for z in [25, 50, 75, 150, 200] {
                    let sel = self.zoom_mode == ZoomMode::Percent && (self.zoom * 100.0).round() as i32 == z;
                    if ui.add(egui::Button::new(format!("{z}%")).selected(sel)).clicked() {
                        self.act(Action::SetZoom(z as f32 / 100.0));
                    }
                }
                ui.separator();
                if item(ui, "Zoom In", "Ctrl+=") {
                    self.act(Action::ZoomIn);
                }
                if item(ui, "Zoom Out", "Ctrl+-") {
                    self.act(Action::ZoomOut);
                }
            });
            ui.separator();
            ui.menu_button("Show/Hide", |ui| {
                ui.checkbox(&mut self.show_toolbar, "Toolbar");
