pub const ZOOM_MAX: f32 = 2.0;
pub const ZOOM_START: f32 = 1.0; // "Standard (100%)"
pub const AUTOSAVE_MIN_DEFAULT: u32 = 10;
pub const APP_NAME: &str = "Scribe Pro";

