    CloseAll,
    Quit,
    Undo,
    Redo,
    Cut,
    Copy,
    Paste,
    SelectAll,
    Dialog(Dialog),
    SetZoom(f32),
    ZoomMode(ZoomMode),
    ZoomIn,
    ZoomOut,
    Draft(bool),
    ToggleDark,
    PageBreak,
    InsertText(String),
    List(ListKind),
    Bold,
    Italic,
    Underline,
    Strike,
    Script(i8),
    Grow,
    Shrink,
    ClearFormat,
    Font(u8),
    Size(f32),
    Color([u8; 3]),
    Highlight(Option<[u8; 3]>),
