#[derive(Clone, Debug, PartialEq)]
pub enum Dialog {
    None,
    Find(bool),
    WordCount,
    PageSetup,
    Paragraph,
    GoTo(usize),
    DateTime,
    Symbol,
    Prefs,
    About,
    Shortcuts,
    DocProps,
    SmartCorrect(String, String),
