                let mx = lay.content_offset.x + l.marker_x;
                page.text(font_res(&CharStyle { bold: false, italic: false, ..s }), s.size, s.color, mx, ph - base, &txt);
            }
        }
        let _ = ListKind::None;
    }

    write_pdf(&pages, pw, ph, &doc.info.title, &doc.info.author)
